 private void startSession(String url){Session previous=session,next=new Session(url,0);session=next;snapshot=null;committed=withPrice=incomplete=pending=0;
  try{writer.execute(()->{try{if(previous!=null&&previous.id>0)store.finishCapture(previous.id,"CLOSED",System.currentTimeMillis());next.id=store.beginCapture(url,System.currentTimeMillis());runOnUiThread(()->{if(!closed&&session==next){bindPage();refreshSnapshot();refreshStatus();}});}catch(RuntimeException error){runOnUiThread(()->{if(!closed&&session==next){deliveryMessage="Ricerca non salvata. Chiudi e riapri per riprovare.";state="CAPTURE_CREATE_ERROR";accepting=false;refreshStatus();}});}});}catch(RejectedExecutionException full){deliveryMessage="Salvataggio occupato. Riprova la ricerca.";state="CAPTURE_CREATE_ERROR";accepting=false;}
 }
 private void resetPage(String url){accepting=false;captureGeneration++;pageGeneration++;navigationUrl=url;pageObserved=pagePrices=0;deliveryMessage="";if(isCatalog(url)){lastSearchUrl=url;if(session==null||!session.key.equals(searchKey(url)))startSession(url);}}
 private void navigate(String url){if(web==null||loading||!VintedBrowserPolicy.allowedPage(url))return;loading=true;accepting=false;refreshStatus();web.loadUrl(url);}
 private void setCapture(boolean value){if(!supported||web==null)return;captureGeneration++;enabled=value;deliveryMessage="";state=value?"CAPTURING":"PAUSED";accepting=value&&resumed&&!loading&&!pageFailed&&session!=null&&session.id>0;web.evaluateJavascript("window.LudoCaptureControl&&window.LudoCaptureControl.setEnabled("+accepting+")",null);refreshStatus();}
