 private void refreshSnapshot(){Session selected=session;if(closed||selected==null||selected.id<=0||snapshotPending)return;snapshotPending=true;reads.execute(()->{BrowserCaptureStore.Snapshot result=null;try{result=store.snapshot(selected.id);}catch(RuntimeException ignored){}final BrowserCaptureStore.Snapshot ready=result;runOnUiThread(()->{snapshotPending=false;if(closed||session!=selected)return;if(ready!=null){snapshot=ready;committed=ready.rows.size();withPrice=0;for(BrowserCaptureStore.Row row:ready.rows)if(row.candidate.priceCents!=null)withPrice++;incomplete=BrowserCapturePresentation.groups(ready).rows("INCOMPLETE").size();}else{deliveryMessage="Conteggi temporaneamente non disponibili.";}refreshStatus();});});}
 private void refreshStatus(){if(controls==null)return;VintedBrowserControls.State model=new VintedBrowserControls.State();model.permittedURL=isCatalog(navigationUrl)?navigationUrl:lastSearchUrl;Uri url=Uri.parse(model.permittedURL);model.query=value(url,"search_text","");model.order=value(url,"order","relevance");model.minCents=price(url.getQueryParameter("price_from"));model.maxCents=price(url.getQueryParameter("price_to"));model.page=pageNumber(navigationUrl);model.catalog=isCatalog(navigationUrl);model.loading=loading;model.supported=supported&&web!=null&&!pageFailed;model.capture=enabled;model.captureId=session==null?0:session.id;model.committed=committed;model.withPrice=withPrice;model.incomplete=incomplete;model.pending=pending;model.message=!supported?"Cattura non disponibile su questa WebView":rendererGone?"Browser interrotto. Chiudi e riapri.":pageFailed?"Pagina non disponibile per la cattura.":deliveryMessage;controls.render(model);saveReport();}
 private void saveReport(){String routeSummary;synchronized(routes){routeSummary=routes.toString();}int localJobs=snapshot==null?0:BrowserCapturePresentation.groups(snapshot).localWork();lastReport="build=browser-durable-capture-v1;app="+BuildConfig.VERSION_NAME+";state="+state+";mode="+mode+";features="+supported+";capture="+enabled+";scope=capture;captureId="+(session==null?0:session.id)+";page="+pageNumber(navigationUrl)+";pageObserved="+pageObserved+";pagePrices="+pagePrices+";committedUnique="+committed+";withPrice="+withPrice+";incomplete="+incomplete+";pendingPackets="+pending+";localWork="+localJobs+";rejectedItems="+rejectedItems+";rejectedPhotos="+rejectedPhotos+";metadataTruncated="+metadataTruncated+";rejected="+rejected.get()+";extraRequestsByCapture=0;networkScope=capturer-only;canonicalWriter=local-analysis;routes="+routeSummary;getSharedPreferences("vinted_browser_experiment",MODE_PRIVATE).edit().putString("report",lastReport).putLong("at",System.currentTimeMillis()).apply();}
 private void observeRoute(Uri uri){if(uri==null||!"https".equals(uri.getScheme())||!("www.vinted.it".equals(uri.getHost())||"vinted.it".equals(uri.getHost())))return;String path=uri.getPath();if(path==null||!path.startsWith("/api/"))return;path=path.replaceAll("[0-9]+","{id}").replaceAll("[^a-zA-Z0-9/{}_\\-]","_");if(path.length()>160)path=path.substring(0,160);synchronized(routes){if(routes.size()<20)routes.add(path);}}
