 private static String sequence(String data){java.util.regex.Matcher m=java.util.regex.Pattern.compile("\"seq\":([0-9]+)").matcher(data.substring(0,Math.min(100,data.length())));return m.find()?m.group(1):"0";}
 private static boolean isCatalog(String url){return url!=null&&Uri.parse(url).getPath()!=null&&Uri.parse(url).getPath().startsWith("/catalog");}
 private static boolean samePage(String a,String b){return a!=null&&b!=null&&Uri.parse(a).buildUpon().fragment(null).build().equals(Uri.parse(b).buildUpon().fragment(null).build());}
 private static String searchKey(String url){Uri uri=Uri.parse(url);List<String> values=new ArrayList<>();for(String key:uri.getQueryParameterNames())if(!key.equals("page"))for(String value:uri.getQueryParameters(key))values.add(key+"="+value);Collections.sort(values);return uri.getPath()+"?"+values;}
 private static int pageNumber(String url){try{return Math.max(1,Math.min(10,Integer.parseInt(Uri.parse(url).getQueryParameter("page"))));}catch(Exception ignored){return 1;}}
 private static String value(Uri url,String key,String fallback){String value=url.getQueryParameter(key);return value==null?fallback:value;}
 private static Integer price(String raw){try{return raw==null?null:new java.math.BigDecimal(raw).movePointRight(2).intValueExact();}catch(Exception ignored){return null;}}
 private int dp(int value){return Math.round(value*getResources().getDisplayMetrics().density);}
